### My answer to the prompt

A reliable way to keep “See more” visible at the end of the line is to render it beside a one-line text element, rather than append it after the full text (which can itself be truncated). The component below measures the text at the available width to decide whether the link should appear.

```jsx
import React, { useEffect, useState } from 'react';
import { Pressable, StyleSheet, Text, View } from 'react-native';

export default function ExpandableText({
  text,
  textStyle,
  seeMoreStyle,
  containerStyle,
  seeMoreLabel = 'See more',
}) {
  const [width, setWidth] = useState(0);
  const [hasOverflow, setHasOverflow] = useState(false);
  const [expanded, setExpanded] = useState(false);

  useEffect(() => {
    setExpanded(false);
    setHasOverflow(false);
  }, [text]);

  const handleMeasure = ({ nativeEvent }) => {
    setHasOverflow(nativeEvent.lines.length > 1);
  };

  return (
    <View style={containerStyle}>
      <View
        style={styles.content}
        onLayout={({ nativeEvent }) => setWidth(nativeEvent.layout.width)}
      >
        {width > 0 && (
          <Text
            pointerEvents="none"
            accessible={false}
            onTextLayout={handleMeasure}
            style={[styles.measureText, textStyle, { width }]}
          >
            {text}
          </Text>
        )}

        {expanded ? (
